import { TranslocoService } from '@jsverse/transloco';
import { ActionContainerComponent } from 'app/common/toolkit/action/action-container.component';
import { Action } from 'app/common/toolkit/action/action.model';
import { Tick } from 'app/common/data/repository/repository.model';
import { Acl } from 'app/common/data/acl/acl.model';
import { SecurityDomain } from 'app/features/access/security-domain/model/security-domain.model';
import { SecurityDomainRepository } from 'app/features/access/security-domain/repository/security-domain-repository.service';
import { computed, input, viewChild, Component, signal, TemplateRef } from '@angular/core';
import { SecurityScopeRepository } from '@features/access/master/security-scope/repository/security-scope-repository.service';
import { ScopeAssignationRepository } from '@features/access/master/scope-assignation/repository/scope-assignation-repository.service';
import { TrustedClientRepository } from '@features/access/master/trusted-client/repository/trusted-client-repository.service';
import { RelyingPartyRepository } from '@features/access/master/relying-party/repository/relying-party-repository.service';
import { ScopeAttributePermissionRepository } from '@features/access/master/scope-attribute-permission/repository/scope-attribute-permission-repository.service';
import { SecurityAttributeRepository } from '@features/access/master/security-attribute/repository/security-attribute-repository.service';
import { RelyingParty } from '@features/access/master/relying-party/model/relying-party.model';
import { TrustedClient } from '@features/access/master/trusted-client/model/trusted-client.model';
import { FormControl, FormGroup } from '@angular/forms';
import { debounceTime } from 'rxjs';
import { SecurityAttribute } from '@features/access/master/security-attribute/model/security-attribute.model';

export class Grouped {
  constructor(
    public readonly resource: string,
    public readonly scopes: GroupedItem[],
  ) {}
}

export class GroupedItem {
  constructor(
    public readonly label: string,
    public readonly uid: string,
    public checked: string | undefined,
    public permision: 'view' | 'modify' | '',
    public version: number,
  ) {}
}

@Component({
  selector: 'security-domain-view-attributes',
  standalone: false,
  templateUrl: './security-domain-view-attributes.component.html',
  styleUrl: './security-domain-view-attributes.component.scss',
})
export class SecurityDomainViewAttributesComponent implements Action {
  readonly name = 'attributes';
  readonly contextual = true;
  readonly multiple = false;
  container = signal<ActionContainerComponent | undefined>(undefined);
  selection = signal<any[]>([]);
  render = viewChild<TemplateRef<any>>('formTemplate');

  title = signal<string>('attributes');
  label = signal<string>('attributes');
  icon = signal<string>('gavel');
  tooltip = signal<string>('attributes');
  default = input<boolean>(false);

  visibleValue = signal(true);
  enabledValue = signal(true);

  form: FormGroup;
  filterResource: string | null = '';
  assignedReferences: { [key: string]: string } = {};
  assignedPermissions: { [key: string]: 'view' | 'modify' } = {};
  assignedVersions: { [key: string]: number } = {};

  allRelies = signal<RelyingParty[]>([]);
  allClients = signal<TrustedClient[]>([]);
  allScopes = signal<Grouped[]>([]);
  filteredScopes = signal<Grouped[]>([]);
  domainAssigned = signal<any>(undefined);
  currentDomain = signal<SecurityDomain | null>(null);

  constructor(
    private readonly scopes: SecurityAttributeRepository,
    private readonly assigned: ScopeAttributePermissionRepository,
    private readonly clients: TrustedClientRepository,
    private readonly parties: RelyingPartyRepository,
    transloco: TranslocoService,
  ) {
    this.form = new FormGroup({
      filter: new FormControl<string>(''),
    });
    this.form.controls['filter'].valueChanges.pipe(debounceTime(500)).subscribe((text) => {
      this.filter(text);
    });

    transloco.selectTranslateObject('action.attributes', {}, 'access/security-domain').subscribe((val) => {
      if (val.label) {
        this.label.set(val.label);
      }
      if (val.tooltip) {
        this.tooltip.set(val.tooltip);
      }
      if (val.icon) {
        this.icon.set(val.icon);
      }
      if (val.title) {
        this.title.set(val.title);
      }
    });
  }

  visible(items: any[]) {
    return this.visibleValue;
  }

  enabled(items: any[]) {
    return this.enabledValue;
  }

  run(): void {
    const domain = this.selection()[0];
    this.allScopes.set([]);
    this.assignedReferences = {};
    this.assignedPermissions = {};
    this.assignedVersions = {};
    this.assigned
      .values({
        securityDomains: [domain.uid],
      })
      .subscribe((all) => {
        all.forEach((item) => {
          this.assignedReferences[item.securityAttribute!.$ref] = item.uid;
          this.assignedPermissions[item.securityAttribute!.$ref] = item.permision;
          this.assignedVersions[item.securityAttribute!.$ref] = item.version || 0;
        });
      });
    this.clients.values({}).subscribe((all) => {
      this.allClients.set(all);
    });
    this.parties.values({}).subscribe((all) => {
      this.allRelies.set(all);
    });
    this.currentDomain.set(domain);
  }

  lookup(event: string) {
    this.allScopes.set([]);
    const parts = event.split(':');
    if (parts[0] == 'client') {
      this.scopes
        .values({
          trustedClients: [parts[1]],
        })
        .subscribe((val) => {
          this.fillOptions(val);
        });
    } else {
      this.scopes
        .values({
          relyingPartys: [parts[1]],
        })
        .subscribe((val) => {
          this.fillOptions(val);
        });
    }
  }

  toogle(item: GroupedItem) {
    const domain = this.selection()[0];
    if (!!item.checked && !item.permision) {
      this.assigned.deleteByKey(item.checked).subscribe();
    } else if (!!item.checked && item.permision) {
      this.assigned
        .update({
          uid: item.checked,
          securityDomain: { $ref: domain.uid },
          securityAttribute: { $ref: item.uid },
          permision: item.permision,
          version: item.version,
        })
        .subscribe();
    } else if (item.permision) {
      this.assigned
        .add({
          uid: '',
          securityDomain: { $ref: domain.uid },
          securityAttribute: { $ref: item.uid },
          permision: item.permision,
          version: item.version,
        })
        .subscribe((cr) => {
          item.checked = cr.uid;
        });
    } else {
      console.error('NO SE QUE HACER', item);
    }
  }

  private fillOptions(val: SecurityAttribute[]) {
    const rows = this.fillGroups(val);
    this.allScopes.set(rows);
    if (this.filterResource) {
      const matcher = new RegExp(this.filterResource);
      this.filteredScopes.set(rows.filter((s) => matcher.test(s.resource)));
    } else {
      this.filteredScopes.set(rows);
    }
  }

  private filter(text: string | null) {
    this.filterResource = text;
    const rows = this.allScopes();
    if (this.filterResource) {
      const matcher = new RegExp(this.filterResource);
      this.filteredScopes.set(rows.filter((s) => matcher.test(s.resource)));
    } else {
      this.filteredScopes.set(rows);
    }
  }

  private fillGroups(all: SecurityAttribute[]): Grouped[] {
    const map = {} as { [key: string]: GroupedItem[] };
    all.forEach((scope) => {
      if (!map[scope.resource]) {
        map[scope.resource] = [];
      }
      const checked = this.assignedReferences[scope.uid] ?? undefined;
      const permision = this.assignedPermissions[scope.uid] ?? '';
      const version = this.assignedVersions[scope.uid] ?? 0;
      map[scope.resource].push(new GroupedItem(scope.attribute, scope.uid, checked, permision, version));
    });
    const result: Grouped[] = [];
    Object.entries(map).forEach(([key, values]) => {
      result.push(new Grouped(key, values));
    });
    return result;
  }
}
